import json
import os

probs = [1.0] * 128

def update_probs(guess_idx, response):
    noise = 0.3
    correct = 0.7
    if response == "equals":
        new_probs = [0.0] * 128
        new_probs[guess_idx] = 1.0
        probs[:] = new_probs
        return
    if response == "higher":
        for i in range(128):
            if i > guess_idx:
                probs[i] *= correct
            elif i < guess_idx:
                probs[i] *= noise
            else:
                probs[i] = 0.0
    elif response == "lower":
        for i in range(128):
            if i < guess_idx:
                probs[i] *= correct
            elif i > guess_idx:
                probs[i] *= noise
            else:
                probs[i] = 0.0
    total = sum(probs)
    if total > 0:
        probs[:] = [p / total for p in probs]

# Load log
with open("/agent/guess_log.json") as f:
    log = json.load(f)

# Apply all responses
for i in range(len(log["guesses"])):
    guess_num = log["guesses"][i]
    response = log["responses"][i]
    guess_idx = guess_num - 1
    update_probs(guess_idx, response)

# Find top 20 probabilities
indexed_probs = [(probs[i], i+1) for i in range(128)]
indexed_probs.sort(reverse=True)

print("Top 20 probabilities:")
for p, num in indexed_probs[:20]:
    print(f"  Number {num}: {p:.8f}")

print(f"\nTotal probability mass: {sum(probs):.6f}")
print(f"Number of non-zero entries: {sum(1 for p in probs if p > 0)}")
EOF
